let fields = [];
try {
    fields = pm.request.body.formdata.toJSON();
} catch (e) {}
const file = fields.find((field) => field.key === "archivos[]" && field.type === "file");
const selected = file && file.src && (!Array.isArray(file.src) || file.src.length > 0);
if (!selected) {
    console.warn("Solicitud omitida: selecciona un archivo de imagen o video en el campo archivos[].");
    pm.execution.skipRequest();
}

pm.test("Carga de evidencia: HTTP 201", () => pm.response.to.have.status(201));
const json = pm.response.json();
pm.test("Se registró al menos una evidencia", () => {
    pm.expect(json.success).to.eql(true);
    pm.expect(json.data).to.be.an("array").that.is.not.empty;
});
if (json.data && json.data.length) {
    pm.collectionVariables.set("idEvidenciaNueva", String(json.data[0].id_evidencia));
}

let fields = [];
try {
    fields = pm.request.body.formdata.toJSON();
} catch (e) {}
const file = fields.find((field) => field.key === "documento" && field.type === "file");
const selected = file && file.src && (!Array.isArray(file.src) || file.src.length > 0);
if (!selected) {
    console.warn("Solicitud omitida: selecciona un PDF, JPG, JPEG o PNG de máximo 5 MB en documento.");
    pm.execution.skipRequest();
}

pm.test("Registrar certificado: HTTP 201", () => pm.response.to.have.status(201));
const json = pm.response.json();
pm.test("Certificado creado y no verificado por defecto", () => {
    pm.expect(json.success).to.eql(true);
    pm.expect(json.data.verificado).to.eql(false);
    pm.expect(json.data).to.not.have.property("ruta_documento");
});
pm.collectionVariables.set("idCertificadoNuevo", String(json.data.id_certificado));

